<div class="page-header"><h1 class="h3 mb-0"><?=($mode??'create')==='edit'?'Edit Expense':'Add Expense'?></h1><a href="<?=url('expenses')?>" class="action-button action-button--neutral btn btn-outline-secondary"><i data-feather="arrow-left" aria-hidden="true"></i>Back</a></div><div class="card"><div class="card-body"><form method="post" enctype="multipart/form-data" action="<?=url(($mode??'create')==='edit'?'expenses/'.$expense['id']:'expenses')?>"><?=csrf_field()?><div class="row"><div class="col-md-4 mb-3"><label class="form-label">Amount *</label><input type="number" step="0.01" min="0.01" class="form-control" name="amount" required value="<?=e($expense['amount']??old('amount'))?>"></div><div class="col-md-4 mb-3"><label class="form-label">Expense Date *</label><input type="date" class="form-control" name="expense_date" required value="<?=e($expense['expense_date']??old('expense_date',date('Y-m-d')))?>"></div><div class="col-md-4 mb-3"><label class="form-label">Status</label><select class="form-select" name="status"><option value="posted" data-icon="check-circle" <?=selected($expense['status']??'posted','posted')?>>Posted</option><option value="draft" data-icon="pause-circle" <?=selected($expense['status']??'','draft')?>>Draft</option></select></div><div class="col-md-6 mb-3"><label class="form-label">Category *</label><select class="form-select" name="category_id" required><option value="" data-icon="tag">Select category</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" data-icon="<?=e($c['display_icon'] ?? $c['icon'] ?? 'tag')?>" <?=selected($expense['category_id']??old('category_id'),$c['id'])?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-6 mb-3"><label class="form-label">Account *</label><select class="form-select" name="account_id" required><option value="" data-icon="credit-card">Select account</option><?php foreach($accounts as $a):?><option value="<?=$a['id']?>" data-account-type="<?=e($a['type'] ?? '')?>" <?=selected($expense['account_id']??old('account_id'),$a['id'])?>><?=e($a['name'])?> (<?=money($a['current_balance'])?>)</option><?php endforeach;?></select></div><div class="col-12 mb-3"><label class="form-label">Description *</label><input class="form-control" name="description" required value="<?=e($expense['description']??old('description'))?>"></div><div class="col-12 mb-3"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="4"><?=e($expense['notes']??old('notes'))?></textarea></div><div class="col-md-6 mb-3"><label for="receipt" class="form-label">Receipt (JPG, PNG, PDF up to 5MB)</label><input id="receipt" type="file" class="form-control" name="receipt" accept="image/jpeg,image/png,application/pdf"><?php if(!empty($expense['receipt_path'])):?><div class="current-file mt-2"><i data-feather="paperclip" aria-hidden="true"></i><span>Current receipt</span><a href="<?=e(url('expenses/'.$expense['id'].'/receipt'))?>" target="_blank" rel="noopener">View file</a></div><?php endif;?></div></div><button class="action-button action-button--success btn btn-primary"><i data-feather="save" aria-hidden="true"></i>Save Expense</button></form></div></div>
